#[capability(
    module = "shopify",
    id = "add-products-to-collection",
    display_name = r##"Add Products To Collection"##,
    description = r##"Adds multiple products to an existing collection in a single operation. This mutation provides an efficient way to bulk-manage collection membership without individual product updates.

For example, when merchants create seasonal collections, they can add dozens of related products at once rather than updating each product individually. A clothing store might add all winter jackets to a "Winter Collection" in one operation.

Use `CollectionAddProducts` to:
- Bulk-add products to collections for efficient catalog management
- Implement collection building tools in admin interfaces
- Organize collection membership during bulk product operations
- Reduce API calls when managing large product sets

The mutation processes multiple product additions and returns success status along with any errors encountered during the operation. Products are added to the collection while preserving existing collection settings.

Learn more about collection management."##,
    side_effects = true,
    rate_limited = true
)]
pub async fn add_products_to_collection(
    input: AddProductsToCollectionInput,
) -> Result<AddProductsToCollectionResult, AgentError> {
    let connection = kit::require_connection(&input._connection, "SHOPIFY")?;
    input.request()?.send(connection, "SHOPIFY").await
}

impl AddProductsToCollectionInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        const DOCUMENT: &str = r##"mutation addProductsToCollection($id: ID!, $productIds: [ID!]!) {
  collectionAddProducts(id: $id, productIds: $productIds) {
    collection {
      id
      title
      productsCount {
        count
      }
    }
    userErrors {
      field
      message
    }
  }
}"##;
        let variables = kit::Body::new()
            .field("id", &self.id)
            .field("productIds", &self.product_ids);
        kit::Request::new("POST", String::from("/admin/api/2026-10/graphql.json")).graphql(
            DOCUMENT,
            "collectionAddProducts",
            false,
            variables,
            "SHOPIFY",
        )
    }
}

